import sys
from collections import deque
import math

# Increase recursion limit
sys.setrecursionlimit(3000)

TARGET_F = 100
MAX_DISTANCE = 20 # Search depth limit
MAX_ABS_N = 150 # State space magnitude limit

memo = {}

def get_valid_choices(N):
    """Finds all valid divisors and multiples X > 1 of N, constrained by MAX_ABS_N."""
    if N <= 1 or abs(N) > MAX_ABS_N:
        return []

    choices = set()

    # 1. Divisors (d | N, d > 1)
    for d in range(2, int(math.sqrt(abs(N))) + 1):
        if N % d == 0:
            if abs(d) <= MAX_ABS_N:
                choices.add(d)
            if abs(N//d) <= MAX_ABS_N:
                choices.add(N // d)

    if abs(N) <= MAX_ABS_N and N > 1:
        choices.add(N) # N itself

    # 2. Multiples (k*N, k >= 2)
    k = 2
    while True:
        multiple = k * N
        if abs(multiple) > MAX_ABS_N:
            break
        choices.add(multiple)
        k += 1

    # Check multiples if N is negative
    if N < 0:
        k = 2
        while True:
            multiple = k * N
            if abs(multiple) > MAX_ABS_N:
                break
            choices.add(multiple)
            k += 1

    return sorted(list(choices))

def solve_D(N):
    if N == TARGET_F:
        return 0

    if abs(N) > MAX_ABS_N:
        return MAX_DISTANCE + 1 # Effectively infinity
    if abs(N) < 2:
        return MAX_DISTANCE + 1

    if N in memo:
        return memo[N]

    valid_X = get_valid_choices(N)

    if not valid_X:
        return MAX_DISTANCE + 1

    min_max_turns = MAX_DISTANCE + 1

    for X in valid_X:
        # Recursively calculate worst-case successor path length
        d_plus = solve_D(X + 1)
        d_minus = solve_D(X - 1)

        worst_case = max(d_plus, d_minus)

        # We choose X to minimize this worst case
        min_max_turns = min(min_max_turns, 1 + worst_case)

    memo[N] = min_max_turns
    return min_max_turns

